56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
64	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String address = normalizeAddress(owner.getAddress());
115	        if (address.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	        }
118	        owner.setAddress(address);
119	        if (owner.getEmail() != null) {
120	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
121	            if (!EMAIL_PATTERN.matcher(email).matches()) {
122	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	            }
124	            owner.setEmail(email);
125	        }
126	        String telephone = normalizeTelephone(owner.getTelephone());
127	        if (telephone == null) {
128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	        }
130	        owner.setTelephone(telephone);
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        if (isTelephoneInUse(telephone)) {
135	            return new ResponseEntity<>(HttpStatus.CONFLICT);
136	        }
137	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner)) {
138	            return new ResponseEntity<>(HttpStatus.CONFLICT);
139	        }
140	        if (countOwnersInCity(owner.getCity()) >= 50) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
144	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
145	        owner.setHouseholdId(householdId(owner));
146	        owner.setNamesakeCount(countNamesakes(owner));
147	        this.clinicService.saveOwner(owner);
148	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
149	        headers.setLocation(UriComponentsBuilder.newInstance()
150	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
151	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
157	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
158	        if (currentOwner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        currentOwner.setAddress(ownerFieldsDto.getAddress());
162	        currentOwner.setCity(ownerFieldsDto.getCity());
163	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
164	        currentOwner.setLastName(ownerFieldsDto.getLastName());
165	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
166	        String email = ownerFieldsDto.getEmail();
167	        if (email != null) {
168	            email = email.trim().toLowerCase(Locale.ROOT);
169	            if (!EMAIL_PATTERN.matcher(email).matches()) {
170	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	            }
172	        }
173	        currentOwner.setEmail(email);
174	        this.clinicService.saveOwner(currentOwner);
175	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Transactional
180	    @Override
181	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        this.clinicService.deleteOwner(owner);
187	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
193	        Owner owner = this.clinicService.findOwnerById(ownerId);
194	        if (owner == null) {
195	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	        }
197	        HttpHeaders headers = new HttpHeaders();
198	        Pet pet = petMapper.toPet(petFieldsDto);
199	        owner.setId(ownerId);
200	        pet.setOwner(owner);
201	        pet.getType().setName(null);
202	        this.clinicService.savePet(pet);
203	        PetDto petDto = petMapper.toPetDto(pet);
204	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
205	            .buildAndExpand(pet.getId()).toUri());
206	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
212	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
213	        if (currentOwner != null) {
214	            Pet currentPet = this.clinicService.findPetById(petId);
215	            if (currentPet != null) {
216	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
217	                currentPet.setName(petFieldsDto.getName());
218	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
219	                this.clinicService.savePet(currentPet);
220	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
221	            }
222	        }
223	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
229	        HttpHeaders headers = new HttpHeaders();
230	        Visit visit = visitMapper.toVisit(visitFieldsDto);
231	        Pet pet = new Pet();
232	        pet.setId(petId);
233	        visit.setPet(pet);
234	        this.clinicService.saveVisit(visit);
235	        VisitDto visitDto = visitMapper.toVisitDto(visit);
236	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
237	            .buildAndExpand(visit.getId()).toUri());
238	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
239	    }
240	
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
245	        Owner owner = this.clinicService.findOwnerById(ownerId);
246	        if (owner != null) {
247	            Pet pet = owner.getPet(petId);
248	            if (pet != null) {
249	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
250	            }
251	        }
252	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
253	    }
254	
255	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
256	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
257	
258	    /**
259	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
260	     * code are kept when present; otherwise country code '+61' is assumed and a single
261	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
262	     * stripped. The result must be a '+' followed by 8 to 15 digits.
263	     * Returns {@code null} when the number cannot form a valid E.164 value.
264	     */
265	    private static String normalizeTelephone(String telephone) {
266	        if (telephone == null) {
267	            return null;
268	        }
269	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
270	        String e164;
271	        if (cleaned.startsWith("+")) {
272	            e164 = cleaned;
273	        } else {
274	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
275	            e164 = "+61" + national;
276	        }
277	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
278	    }
279	
280	    /**
281	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
282	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
283	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
284	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
285	     */
286	    private String generateCustomerCode(String city, String lastName) {
287	        String city3 = firstThreeLetters(city);
288	        String last3 = firstThreeLetters(lastName);
289	        int sequence = countOwnersInCity(city) + 1;
290	        return String.format("%s-%s-%04d", city3, last3, sequence);
291	    }
292	
293	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
294	    private static String firstThreeLetters(String value) {
295	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
296	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
297	    }
298	
299	    /**
300	     * The number of existing owners registered in {@code city}, compared case-insensitively
301	     * with collapsed whitespace.
302	     */
303	    private int countOwnersInCity(String city) {
304	        String normalized = normalizeHouseholdField(city);
305	        return (int) this.clinicService.findAllOwners().stream()
306	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
307	            .count();
308	    }
309	
310	    /**
311	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
312	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
313	     */
314	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
315	        String yy = String.format("%02d", registrationDate.getYear() % 100);
316	        return customerCode + "-M" + yy;
317	    }
318	
319	    /**
320	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
321	     * last name, compared case-insensitively.
322	     */
323	    private int countNamesakes(Owner owner) {
324	        String firstName = normalizeHouseholdField(owner.getFirstName());
325	        String lastName = normalizeHouseholdField(owner.getLastName());
326	        return (int) this.clinicService.findAllOwners().stream()
327	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
328	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
329	            .count();
330	    }
331	
332	    /** Whether any existing owner already uses the given (E.164) telephone number. */
333	    private boolean isTelephoneInUse(String telephone) {
334	        return this.clinicService.findAllOwners().stream()
335	            .map(Owner::getTelephone)
336	            .filter(existing -> existing != null)
337	            .map(OwnerRestControllerV1::normalizeTelephone)
338	            .filter(existing -> existing != null)
339	            .anyMatch(telephone::equals);
340	    }
341	
342	    /** Common street-type abbreviations expanded during address normalization. */
343	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
344	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
345	
346	    /**
347	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
348	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
349	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
350	     * string when {@code address} is null or blank after normalization.
351	     */
352	    private static String normalizeAddress(String address) {
353	        if (address == null) {
354	            return "";
355	        }
356	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
357	        if (collapsed.isEmpty()) {
358	            return "";
359	        }
360	        StringBuilder sb = new StringBuilder(collapsed.length());
361	        for (String token : collapsed.split(" ")) {
362	            if (sb.length() > 0) {
363	                sb.append(' ');
364	            }
365	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
366	        }
367	        return sb.toString();
368	    }
369	
370	    /**
371	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
372	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
373	     */
374	    private static String normalizeHouseholdField(String value) {
375	        if (value == null) {
376	            return "";
377	        }
378	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
379	    }
380	
381	    /**
382	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
383	     * same address compared case-insensitively with collapsed whitespace.
384	     */
385	    private List<Owner> findHousemates(Owner owner) {
386	        String lastName = normalizeHouseholdField(owner.getLastName());
387	        String address = normalizeHouseholdField(owner.getAddress());
388	        return this.clinicService.findAllOwners().stream()
389	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
390	                && normalizeHouseholdField(existing.getAddress()).equals(address))
391	            .toList();
392	    }
393	
394	    /**
395	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
396	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
397	     */
398	    private boolean isHouseholdInUse(Owner owner) {
399	        return !findHousemates(owner).isEmpty();
400	    }
401	
402	    /**
403	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
404	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
405	     * deterministically from those normalized fields so housemates always resolve to the same value,
406	     * regardless of registration order.
407	     */
408	    private static String householdId(Owner owner) {
409	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
410	            + normalizeHouseholdField(owner.getAddress());
411	        try {
412	            byte[] digest = MessageDigest.getInstance("SHA-256")
413	                .digest(key.getBytes(StandardCharsets.UTF_8));
414	            StringBuilder sb = new StringBuilder(24);
415	            for (int i = 0; i < 12; i++) {
416	                sb.append(String.format("%02X", digest[i]));
417	            }
418	            return sb.toString();
419	        }
420	        catch (NoSuchAlgorithmException e) {
421	            throw new IllegalStateException("SHA-256 not available", e);
422	        }
423	    }
424	}
